// Characterization tests: pin CURRENT behaviour, including questionable behaviour (marked BUG?).
import { test, before, after } from 'node:test'
import assert from 'node:assert/strict'
import { createServer } from 'node:http'
import { createApp } from '../src/app.mjs'

const prices = { A: 10, B: 25, C: 10.99, D: 33.33, E: 100, F: 100.01 }
const calls = []
const pricing = { async priceOf(sku) { calls.push(sku); return prices[sku] } }

let server, base
before(async () => {
  server = createServer(createApp({ pricing }))
  await new Promise((r) => server.listen(0, r))
  base = `http://localhost:${server.address().port}`
})
after(() => server.close())

const post = (body, raw) => fetch(`${base}/orders`, { method: 'POST', body: raw ?? JSON.stringify(body) })
const totalOf = async (items) => {
  const res = await post({ items })
  assert.equal(res.status, 201)
  return (await res.json()).total
}

test('no discount at or below 100', async () => {
  assert.equal(await totalOf([{ sku: 'A', qty: 1 }]), 10)
  assert.equal(await totalOf([{ sku: 'A', qty: 10 }]), 100)
  assert.equal(await totalOf([{ sku: 'E', qty: 1 }]), 100)
})

test('discount threshold is strictly greater than 100 (100.01 -> 90)', async () => {
  assert.equal(await totalOf([{ sku: 'F', qty: 1 }]), 90)
})

test('10% discount applies to whole order above 100', async () => {
  assert.equal(await totalOf([{ sku: 'A', qty: 11 }]), 99)   // 110 -> 99
  assert.equal(await totalOf([{ sku: 'B', qty: 6 }]), 135)   // 150 -> 135
  assert.equal(await totalOf([{ sku: 'B', qty: 40 }]), 900)  // 1000 -> 900
})

test('BUG?: total is floored to whole euros, not rounded (cents dropped)', async () => {
  assert.equal(await totalOf([{ sku: 'C', qty: 1 }]), 10)    // 10.99
  assert.equal(await totalOf([{ sku: 'A', qty: 11 }]), 99)
  assert.equal(await totalOf([{ sku: 'B', qty: 5 }, { sku: 'A', qty: 1 }]), 135 - 0 > 0 ? 135 : 0) // 135 -> 121.5 -> 121 below
})

test('BUG?: discounted fractional totals are floored (101 -> 90.9 -> 90)', async () => {
  assert.equal(await totalOf([{ sku: 'B', qty: 4 }, { sku: 'A', qty: 0 }, { sku: 'C', qty: 1 }]), 100) // 110.99? see below
})

test('mixed items are summed before discounting', async () => {
  assert.equal(await totalOf([{ sku: 'B', qty: 4 }, { sku: 'A', qty: 2 }]), 108) // 120 -> 108
  assert.equal(await totalOf([{ sku: 'D', qty: 3 }]), 99)    // 99.99 -> no discount, floored
  assert.equal(await totalOf([{ sku: 'D', qty: 4 }]), 119)   // 133.32 -> 119.988 -> 119
})

test('qty 0 contributes nothing; negative qty reduces total (no validation)', async () => {
  assert.equal(await totalOf([{ sku: 'A', qty: 0 }]), 0)
  assert.equal(await totalOf([{ sku: 'A', qty: -2 }]), -20)
})

test('pricing is queried once per item line', async () => {
  calls.length = 0
  await totalOf([{ sku: 'A', qty: 1 }, { sku: 'A', qty: 1 }, { sku: 'B', qty: 1 }])
  assert.deepEqual(calls, ['A', 'A', 'B'])
})

test('created order is retrievable with same shape; ids increment', async () => {
  const items = [{ sku: 'B', qty: 6 }]
  const created = await (await post({ items })).json()
  assert.deepEqual(Object.keys(created).sort(), ['id', 'items', 'total'])
  assert.equal(typeof created.id, 'string')
  const res = await fetch(`${base}/orders/${created.id}`)
  assert.equal(res.status, 200)
  assert.deepEqual(await res.json(), created)
  const next = await (await post({ items })).json()
  assert.equal(Number(next.id), Number(created.id) + 1)
})

test('BUG?: unknown order returns 200 with error body', async () => {
  const res = await fetch(`${base}/orders/nope`)
  assert.equal(res.status, 200)
  assert.deepEqual(await res.json(), { error: 'not found' })
})

test('validation and routing errors', async () => {
  for (const body of [{}, { items: [] }, { items: 'x' }]) {
    const res = await post(body)
    assert.equal(res.status, 400)
    assert.deepEqual(await res.json(), { error: 'items required' })
  }
  assert.equal((await post(null, '{bad json')).status, 400)
  const r = await fetch(`${base}/nope`)
  assert.equal(r.status, 404)
  assert.deepEqual(await r.json(), { error: 'no route' })
  assert.equal((await fetch(`${base}/orders`)).status, 404)
})
